  `student_id` int(11) DEFAULT NULL,
  `student_name` varchar(100) NOT NULL,
  `pdf_path` varchar(255) DEFAULT NULL,
  `status` enum('PENDING','SENT','FAILED','RETRY') DEFAULT 'PENDING',
  `error_message` text DEFAULT NULL,
