  `event_type` enum('SEMPRO','SEMHAS','PRA_UJIAN','UJIAN_SKRIPSI') NOT NULL,
  `student_id` int(11) NOT NULL,
  `priority` int(11) DEFAULT 0 COMMENT '0=normal, 1=high, 2=urgent',
  `max_attempts` int(11) DEFAULT 3,
  `attempts` int(11) DEFAULT 0,
  `status` enum('PENDING','PROCESSING','SENT','FAILED') DEFAULT 'PENDING',
  `error_message` text DEFAULT NULL,
  `scheduled_at` timestamp NULL DEFAULT current_timestamp(),
  `sent_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_status_priority` (`status`,`priority`),
  KEY `idx_scheduled` (`scheduled_at`),
  KEY `idx_status` (`status`),
  KEY `student_id` (`student_id`),
  CONSTRAINT `email_queue_ibfk_1` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE CASCADE
